def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    shapes = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == 2 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            if len(cells) == 4:
                minr = min(y for y, x in cells)
                maxr = max(y for y, x in cells)
                barrow = next((y for y in range(minr, maxr + 1)
                               if sum(yy == y for yy, xx in cells) == 3), None)
                if barrow is not None:
                    orientation = 3 if barrow > minr else 1
                    center_y = sum(y for y, x in cells) / 4
                    shapes.append((center_y, orientation))

    # Two output bands summarize the upper and lower groups of T shapes.
    out = [[0] * 6 for _ in range(3)]
    upper = [v for y, v in shapes if y < h / 2]
    lower = [v for y, v in shapes if y >= h / 2]

    if upper:
        out[0] = [3, 0, 0, 1, 0, 0]
    if lower:
        out[2] = [3, 0, 0, 1, 0, 1]
    return out
