            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            if len(cells) == 4:
                objects.append(cells)

    out = [[0] * 6 for _ in range(3)]
    for cells in objects:
        cy = sum(y for y, x in cells) / 4
        cx = sum(x for y, x in cells) / 4
        row = 0 if cy < h / 2 else 2
        # T's on the left half are represented by 3, those on the right by 1.
        if cx < w / 2:
            col = 0 if cx < w / 3 else 2
            val = 3
        else:
            col = 3 if cx < 2 * w / 3 else 5
            val = 1
        out[row][col] = val
    return out
